148	// Helper to create request context with proper linking and cancellation handling
149	fn create_request_context(
150	    request: rmpv::Value,
151	    parent_ctx: &Option<context::Context>,
152	) -> RsContext<rmpv::Value> {
153	    match parent_ctx {
154	        // If there is a parent context, link the request as a child context of it
155	        Some(parent_ctx) => {
156	            let child_ctx = RsContext::with_id_and_metadata(
157	                request,
158	                parent_ctx.inner().id().to_string(),
159	                parent_ctx.metadata_snapshot(),
160	            );
161	            parent_ctx.inner().link_child(child_ctx.context());
162	            if parent_ctx.inner().is_stopped() || parent_ctx.inner().is_killed() {
163	                // Let the server handle the cancellation for now since not all backends are
164	                // properly handling request exceptions
165	                // TODO: (DIS-830) Return an error if context is cancelled
166	                child_ctx.context().stop_generating();
167	            }
168	            child_ctx
169	        }
170	        // Otherwise if there is no parent context, use the request as-is
171	        _ => request.into(),
172	    }
173	}
