272	pub(crate) fn worker_selection_policy_factory(
273	    config: &KvRouterConfig,
274	) -> anyhow::Result<Option<WorkerSelectionPolicyFactory>> {
275	    #[cfg(feature = "custom-policy")]
276	    {
277	        Ok(WORKER_SELECTION_POLICY_REGISTRY
278	            .get()
279	            .map(|registry| registry.resolve(config))
280	            .transpose()?
281	            .flatten())
282	    }
283	
284	    #[cfg(not(feature = "custom-policy"))]
285	    {
286	        if let Some(instance) = config.selected_worker_selection_policy_instance()? {
287	            anyhow::bail!(
288	                "worker-selection instance {instance:?} is configured, but this Dynamo build has no linked worker-selection policy catalog; rebuild with --features custom-policy"
289	            );
290	        }
291	        Ok(None)
292	    }
293	}
