308	/// Resolve only the aggregated policy used by standalone selection hosts.
309	pub(crate) fn standalone_worker_selection_policy_factory(
310	    config: &KvRouterConfig,
311	) -> anyhow::Result<Option<WorkerSelectionPolicyFactory>> {
312	    warn_if_standalone_ignores_stage_policies(config)?;
313	
314	    #[cfg(feature = "custom-policy")]
315	    {
316	        Ok(WORKER_SELECTION_POLICY_REGISTRY
317	            .get()
318	            .map(|registry| {
319	                registry.resolve_for_worker_type(config, dynamo_kv_router::WorkerType::Aggregated)
320	            })
321	            .transpose()?
322	            .flatten())
323	    }
324	
325	    #[cfg(not(feature = "custom-policy"))]
326	    {
327	        if let Some(instance) = config.selected_worker_selection_policy_instance_for(
328	            dynamo_kv_router::WorkerType::Aggregated,
329	        )? {
330	            anyhow::bail!(
331	                "worker-selection instance {instance:?} is configured, but this Dynamo build has no linked worker-selection policy catalog; rebuild with --features custom-policy"
332	            );
333	        }
334	        Ok(None)
335	    }
336	}
