339	fn register_core_with_custom_worker_selection_policy(m: &Bound<'_, PyModule>) -> PyResult<()> {
340	    let mut registry = WorkerSelectionPolicyRegistry::default();
341	    dynamo_worker_selection_policy_catalog::register(&mut registry)
342	        .map_err(|error| PyRuntimeError::new_err(error.to_string()))?;
343	
344	    WORKER_SELECTION_POLICY_REGISTRY
345	        .set(registry)
346	        .map_err(|_| {
347	            PyRuntimeError::new_err("worker-selection policy registry already installed")
348	        })?;
349	    register_core(m)
350	}
