373	fn standalone_to_pyerr(err: anyhow::Error) -> PyErr {
374	    #[cfg(any(
375	        feature = "kv-indexer",
376	        feature = "slot-tracker",
377	        feature = "select-service"
378	    ))]
379	    if let Some(clap_error) = err.downcast_ref::<clap::Error>() {
380	        let _ = clap_error.print();
381	        return pyo3::exceptions::PySystemExit::new_err(clap_error.exit_code());
382	    }
383	
384	    to_pyerr(err)
385	}
