387	fn resolve_event_transport_kind(
388	    discovery_backend: &DiscoveryBackend,
389	    event_plane: Option<&str>,
390	) -> PyResult<EventTransportKind> {
391	    match event_plane {
392	        Some("nats") => Ok(EventTransportKind::Nats),
393	        Some("zmq") => Ok(EventTransportKind::Zmq),
394	        Some("") | None => Ok(discovery_backend.resolve_event_transport_kind()),
395	        Some(other) => Err(PyValueError::new_err(format!(
396	            "Invalid event_plane value '{other}'. Valid values: 'nats', 'zmq'"
397	        ))),
398	    }
399	}
