454	/// Resolve the routing-side image-placeholder token id for a model using the
455	/// frontend's static per-family logic. Returns `chat_placeholder_token_id` —
456	/// the exact id `OpenAIPreprocessor` substitutes `pad_value` over.
457	///
458	/// `model_id` is the HF id (used for registry matching); `model_dir` is the
459	/// local directory holding the model configs. Returns `None` when the
460	/// placeholder, prompt layout, or image-token counter cannot be resolved, so
461	/// the worker never enables image-key normalization while the frontend is
462	/// limited to text-prefix routing. Request-time frontend gates are preserved
463	/// because event normalization only recognizes frontend-issued canonical MM
464	/// UUIDs.
465	#[cfg(feature = "mm-routing")]
466	#[pyfunction]
467	#[pyo3(text_signature = "(model_id, model_dir)")]
468	fn resolve_routing_image_token_id(model_id: &str, model_dir: &str) -> Option<u32> {
469	    let dir = std::path::Path::new(model_dir);
470	    llm_rs::preprocessor::lightseek_mm::resolve_exact_routing_image_token_id(model_id, dir)
471	}
