473	/// Create an engine and attach it to an endpoint to make it visible to the frontend.
474	/// This is the main way you create a Dynamo worker / backend.
475	///
476	/// If `lora_name` is provided, this function will publish a LoRA adapter instead of a base model:
477	/// - LoRA path: v1/mdc/{namespace}/{component}/{endpoint}/{instance_id}/{lora_slug}
478	/// - Base model path: v1/mdc/{namespace}/{component}/{endpoint}/{instance_id}
479	///
480	/// For LoRA mode, both `lora_name` and `base_model_path` must be provided together.
481	/// Providing only one of them will result in an error.
482	#[pyfunction]
483	#[pyo3(signature = (model_input, model_type, endpoint, model_path, model_name=None, kv_cache_block_size=None, router_config=None, runtime_config=None, user_data=None, custom_template_path=None, media_decoder=None, media_fetcher=None, lora_name=None, base_model_path=None, worker_type=None, needs=None, self_host_metadata=None, *, tensor_model_config=None, ignore_weights=false, max_gpu_lora_count=None, model_aliases=None))]
484	#[allow(clippy::too_many_arguments)]
485	fn register_model<'p>(
486	    py: Python<'p>,
487	    model_input: ModelInput,
488	    model_type: ModelType,
489	    endpoint: Endpoint,
490	    model_path: &str,
491	    model_name: Option<&str>,
492	    kv_cache_block_size: Option<u32>,
493	    router_config: Option<PyRouterConfig>,
494	    runtime_config: Option<ModelRuntimeConfig>,
495	    user_data: Option<&Bound<'p, PyDict>>,
496	    custom_template_path: Option<&str>,
497	    media_decoder: Option<MediaDecoder>,
498	    media_fetcher: Option<MediaFetcher>,
499	    lora_name: Option<&str>,
500	    base_model_path: Option<&str>,
501	    worker_type: Option<WorkerType>,
502	    needs: Option<Vec<Vec<WorkerType>>>,
503	    self_host_metadata: Option<bool>,
504	    tensor_model_config: Option<&Bound<'p, PyDict>>,
505	    ignore_weights: bool,
506	    max_gpu_lora_count: Option<u32>,
507	    model_aliases: Option<Vec<String>>,
508	) -> PyResult<Bound<'p, PyAny>> {
509	    // Every worker registers with an explicit `worker_type`. Reject `None`
510	    // outright — a missing role would produce a card whose readiness math
511	    // is undefined and whose ws_key would collide with other Aggregated
512	    // workers in the same namespace.
513	    let Some(worker_type_unwrapped) = worker_type else {
514	        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
515	            "register_model: `worker_type` is required. Pass one of \
516	             WorkerType.Prefill / Decode / Encode / Aggregated.",
517	        ));
518	    };
519	
520	    // Prefill and Encode workers receive pre-tokenized requests (their engines
521	    // preprocess externally), so both require `ModelInput::Tokens`.
522	    if matches!(
523	        worker_type_unwrapped,
524	        WorkerType::Prefill | WorkerType::Encode
525	    ) && !matches!(model_input, ModelInput::Tokens)
526	    {
527	        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
528	            "register_model: worker_type={:?} requires model_input=ModelInput::Tokens",
529	            worker_type_unwrapped
530	        )));
531	    }
532	
533	    // Prefill workers never expose an OpenAI surface — they are reached only
534	    // through the dedicated prefill router, never by the frontend. They MAY,
535	    // however, carry the legacy `ModelType.Prefill` *marker* bit, which new
536	    // prefill workers dual-emit so an old frontend still detects them during
537	    // the cross-version rollout (see `ModelType::Prefill`). So the only thing we
538	    // reject here is a genuine OpenAI *surface* on a prefill card. Encode
539	    // workers MAY carry a surface: an sglang multimodal encode worker is the
540	    // OpenAI front door that delegates generation to an internal worker,
541	    // whereas a vLLM-style encode helper registers Empty. Serving is driven by
542	    // `ModelType` (the OpenAI surface); the topology role is by `worker_type`.
543	    if matches!(worker_type_unwrapped, WorkerType::Prefill) {
544	        // Strip the allowed Prefill marker bit; whatever remains is a surface.
545	        let surface = model_type.inner - llm_rs::model_type::ModelType::Prefill;
546	        if !surface.is_empty() {
547	            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
548	                "register_model: worker_type={:?} must not expose an OpenAI surface \
549	                 (got model_type={:?}). Use ModelType.Empty or ModelType.Prefill; \
550	                 the prefill role is carried by worker_type, and ModelType only \
551	                 describes the OpenAI surface, which prefill workers don't expose.",
552	                worker_type_unwrapped, model_type.inner
553	            )));
554	        }
555	    }
556	
557	    let model_input = match model_input {
558	        ModelInput::Text => llm_rs::model_type::ModelInput::Text,
559	        ModelInput::Tokens => llm_rs::model_type::ModelInput::Tokens,
560	        ModelInput::Tensor => llm_rs::model_type::ModelInput::Tensor,
561	    };
562	
563	    let is_tensor_based = model_type.inner.supports_tensor();
564	    let is_images = model_type.inner.supports_images();
565	    let is_videos = model_type.inner.supports_videos();
566	    let is_realtime = model_type.inner.supports_realtime();
567	
568	    let model_type_obj = model_type.inner;
569	    let tensor_model_config = parse_tensor_model_config(tensor_model_config)?;
570	    if tensor_model_config.is_some() && !is_tensor_based {
571	        return Err(PyValueError::new_err(
572	            "tensor_model_config is only valid for TensorBased models",
573	        ));
574	    }
575	
576	    // Model-serving-readiness fields on the MDC. `worker_type` is required
577	    // (see the check above). Non-Aggregated workers must declare their peers
578	    // explicitly — an empty `needs` would make them immediately ready with
579	    // no dependencies, which is only correct for Aggregated.
580	    let worker_type_value: Option<llm_rs::worker_type::WorkerType> =
581	        Some(worker_type_unwrapped.into());
582	    let raw_needs: Vec<Vec<WorkerType>> = match (worker_type_unwrapped, needs) {
583	        (WorkerType::Aggregated, None) => Vec::new(),
584	        (WorkerType::Aggregated, Some(n)) => n,
585	        (_, None) => {
586	            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
587	                "register_model: worker_type={:?} requires a non-empty `needs` \
588	                 (at least one peer worker type the role depends on)",
589	                worker_type_unwrapped
590	            )));
591	        }
592	        (_, Some(n)) if n.is_empty() => {
593	            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
594	                "register_model: worker_type={:?} requires a non-empty `needs` \
595	                 (at least one peer worker type the role depends on)",
596	                worker_type_unwrapped
597	            )));
598	        }
599	        (_, Some(n)) => n,
600	    };
601	    let needs_value: Vec<Vec<llm_rs::worker_type::WorkerType>> = raw_needs
602	        .into_iter()
603	        .map(|alt| alt.into_iter().map(|w| w.into()).collect())
604	        .collect();
605	
606	    let inner_path = model_path.to_string();
607	    let model_name = model_name.map(|n| n.to_string());
608	    // Only embed router_config in the MDC when the caller explicitly provided it.
609	    // This preserves backward-compat: workers that don't specify router_config continue to
610	    // fall back to the frontend-level global router config via the watcher.
611	    let explicit_router_config: Option<RouterConfig> = router_config.map(|rc| rc.into());
612	    let model_aliases = model_aliases.unwrap_or_default();
613	
614	    // Early validation of custom template path
615	    let custom_template_path_owned = custom_template_path
616	        .map(|s| {
617	            let path = PathBuf::from(s);
618	            if !path.exists() {
619	                return Err(PyErr::new::<pyo3::exceptions::PyFileNotFoundError, _>(
620	                    format!("Custom template file does not exist: {}", path.display()),
621	                ));
622	            }
623	            Ok(path)
624	        })
625	        .transpose()?;
626	
627	    let user_data_json = user_data
628	        .map(|dict| pythonize::depythonize(dict))
629	        .transpose()
630	        .map_err(|err| {
631	            PyErr::new::<PyException, _>(format!("Failed to convert user_data: {}", err))
632	        })?;
633	
634	    // Validate LoRA parameters: both or neither must be provided
635	    if lora_name.is_some() ^ base_model_path.is_some() {
636	        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
637	            "lora_name and base_model_path must both be provided together, or neither",
638	        ));
639	    }
640	
641	    // Determine source_path and lora_identifier based on registration mode
642	    let (source_path, lora_identifier) = match (lora_name, base_model_path) {
643	        (Some(lora), Some(base)) => (base.to_string(), Some(lora.to_string())),
644	        _ => (inner_path, None),
645	    };
646	
647	    // Model name: use lora name if present, otherwise provided name or default to source path
648	    let model_name = lora_identifier
649	        .clone()
650	        .or(model_name)
651	        .or_else(|| Some(source_path.clone()));
652	
653	    if let Some(cfg) = &runtime_config {
654	        cfg.validate_config()?;
655	    }
656	
657	    pyo3_async_runtimes::tokio::future_into_py(py, async move {
658	        let runtime_config = runtime_config.unwrap_or_default();
659	
660	        // For TensorBased, Images, Videos, and Realtime models, skip
661	        // HuggingFace downloads and register directly. These model types
662	        // handle model loading internally; no tokenizer extraction is
663	        // needed and the source path is not required to be a HF repo.
664	        if is_tensor_based || is_images || is_videos || is_realtime {
665	            let model_name = model_name.unwrap_or_else(|| source_path.clone());
666	            let mut card = llm_rs::model_card::ModelDeploymentCard::with_name_only(&model_name);
667	            // Preserve source_path for compatibility checks (LoRA vs base model).
668	            // Only set if it differs from model_name to preserve legacy MDC checksums.
669	            if source_path != model_name {
670	                card.source_path = Some(source_path.clone());
671	            }
672	
673	            // Populate lora_info if this is a LoRA registration.
674	            if let Some(lora_name) = lora_identifier.clone() {
675	                card.lora = Some(llm_rs::model_card::LoraInfo {
676	                    name: lora_name,
677	                    max_gpu_lora_count,
678	                });
679	            }
680	            card.model_type = model_type_obj;
681	            card.model_input = model_input;
682	            card.worker_type = worker_type_value;
683	            card.needs = needs_value.clone();
684	            card.user_data = user_data_json;
685	            // Aliases are only honored on the LLM surfaces (their handlers
686	            // canonicalize alias→primary); ignore them for these types.
687	            if !model_aliases.is_empty() {
688	                tracing::warn!(
689	                    model_name = %model_name,
690	                    "Ignoring served-model-name aliases: not supported for \
691	                     tensor/images/videos/realtime models"
692	                );
693	            }
694	
695	            // For base model (no lora_identifier), propagate LoRA slot capacity so
696	            // frontend allocator can see idle-but-LoRA-capable workers before first adapter load.
697	            let mut rc = runtime_config.inner;
698	            if lora_identifier.is_none() {
699	                rc.max_gpu_lora_count = max_gpu_lora_count;
700	            }
701	            card.runtime_config = rc;
702	            card.tensor_model_config = tensor_model_config;
703	            card.router_config = explicit_router_config.clone();
704	
705	            // Register the Model Deployment Card via discovery interface
706	            register_model_card(&endpoint.inner, &card)
707	                .await
708	                .map_err(|e| PyException::new_err(format!("{}", e)))?;
709	
710	            return Ok(());
711	        }
712	
713	        // For non-TensorBased models, resolve the model path (local or fetch from HuggingFace).
714	        // ModelExpress load paths pass ignore_weights=true because the engine already owns
715	        // weight acquisition; other load paths keep the default full-fetch behavior.
716	        let model_path = if fs::exists(&source_path)? {
717	            PathBuf::from(&source_path)
718	        } else {
719	            LocalModel::fetch(&source_path, ignore_weights)
720	                .await
721	                .map_err(to_pyerr)?
722	        };
723	
724	        let mut builder = dynamo_llm::local_model::LocalModelBuilder::default();
725	        builder
726	            // model path is the physical path on disk of the downloaded model
727	            .model_path(model_path)
728	            // source path is what the user gave as `--model-path`, either a real path (in which
729	            // case it matches model_path above), or an HF repo.
730	            .source_path(source_path.clone().into())
731	            // --served_model_name
732	            .model_name(model_name.clone())
733	            // --served_model_name aliases (additional names this model responds to)
734	            .model_aliases(model_aliases)
735	            .kv_cache_block_size(kv_cache_block_size)
736	            .router_config(explicit_router_config.clone())
737	            .runtime_config({
738	                let mut rc = runtime_config.inner;
739	                // The base worker registration carries the worker's LoRA slot capacity so the
740	                // frontend allocator sees idle-but-LoRA-capable workers before any adapter is
741	                // loaded. Adapter registrations (lora_name set) carry it via LoraInfo instead.
742	                if lora_identifier.is_none() {
743	                    rc.max_gpu_lora_count = max_gpu_lora_count;
744	                }
745	                rc
746	            })
747	            .user_data(user_data_json)
748	            .custom_template_path(custom_template_path_owned)
749	            .media_decoder(media_decoder.map(|m| m.inner))
750	            .media_fetcher(media_fetcher.map(|m| m.inner));
751	        // Absence falls through to the DYN_SELF_HOST_METADATA env var default.
752	        if let Some(enabled) = self_host_metadata {
753	            builder.self_host_metadata(enabled);
754	        }
755	
756	        let mut local_model = builder.build().await.map_err(to_pyerr)?;
757	
758	        // Convert lora_identifier (Option<String>) to Option<LoraInfo>
759	        let lora_info = lora_identifier
760	            .as_ref()
761	            .map(|name| llm_rs::model_card::LoraInfo {
762	                name: name.clone(),
763	                max_gpu_lora_count,
764	            });
765	
766	        local_model
767	            .attach(
768	                &endpoint.inner,
769	                model_type_obj,
770	                model_input,
771	                lora_info,
772	                worker_type_value,
773	                needs_value,
774	            )
775	            .await
776	            .map_err(to_pyerr)?;
777	
778	        if let Some(lora_name) = lora_identifier {
779	            tracing::info!("Registered LoRA '{}' MDC", lora_name);
780	        } else {
781	            tracing::info!(
782	                "Registered base model '{}' MDC",
783	                model_name.unwrap_or(source_path)
784	            );
785	        }
786	
787	        Ok(())
788	    })
789	}
