791	/// Unregister a Model Deployment Card (MDC) from the service registry
792	///
793	/// This removes an LLM deployment from the discovery system.
794	///
795	/// # Arguments
796	///
797	/// * `endpoint` - The endpoint where the model is registered
798	/// * `lora_name` - Optional LoRA adapter name (if unregistering a LoRA deployment)
799	///
800	/// # MDC Path Format
801	///
802	/// - Base model: `v1/mdc/{namespace}/{component}/{endpoint}/{instance_id}`
803	/// - LoRA model: `v1/mdc/{namespace}/{component}/{endpoint}/{instance_id}/{lora_slug}`
804	#[pyfunction]
805	#[pyo3(signature = (endpoint, lora_name=None))]
806	fn unregister_model<'p>(
807	    py: Python<'p>,
808	    endpoint: Endpoint,
809	    lora_name: Option<&str>,
810	) -> PyResult<Bound<'p, PyAny>> {
811	    let lora_name_owned = lora_name.map(|s| s.to_string());
812	
813	    pyo3_async_runtimes::tokio::future_into_py(py, async move {
814	        // Unified detach method handles both base models and LoRA adapters
815	        LocalModel::detach_from_endpoint(&endpoint.inner, lora_name_owned.as_deref())
816	            .await
817	            .map_err(to_pyerr)?;
818	        Ok(())
819	    })
820	}
