1308	    /// Register an async Python callback for /engine/{route_name}
1309	    ///
1310	    /// Args:
1311	    ///     route_name: Route path (e.g., "control/start_profile" → /engine/control/start_profile)
1312	    ///     callback: Async function with signature: async def(body: dict) -> dict
1313	    ///
1314	    /// Example:
1315	    /// ```python
1316	    /// async def start_profile(body: dict) -> dict:
1317	    ///     await engine.start_profile(**body)
1318	    ///     return {"status": "ok"}
1319	    ///
1320	    /// runtime.register_engine_route("control/start_profile", start_profile)
1321	    /// ```
1322	    #[pyo3(signature = (route_name, callback))]
1323	    fn register_engine_route(
1324	        &self,
1325	        py: Python<'_>,
1326	        route_name: String,
1327	        callback: PyObject,
1328	    ) -> PyResult<()> {
1329	        // Capture TaskLocals at registration time when Python's event loop is running.
1330	        // This is needed because later, when the callback is invoked from an HTTP request,
1331	        // we'll be on a Rust thread without a running Python event loop.
1332	        let locals =
1333	            Arc::new(pyo3_async_runtimes::tokio::get_current_locals(py).map_err(to_pyerr)?);
1334	        let callback = Arc::new(callback);
1335	
1336	        // Wrap Python async callback in Rust async closure
1337	        let rust_callback: rs::engine_routes::EngineRouteCallback =
1338	            Arc::new(move |body: serde_json::Value| {
1339	                let callback = callback.clone();
1340	                let locals = locals.clone();
1341	
1342	                // Return a boxed future
1343	                Box::pin(async move {
1344	                    // Acquire GIL to call Python callback and convert coroutine to future
1345	                    let py_future = Python::with_gil(|py| {
1346	                        // Convert body to Python dict
1347	                        let py_body = pythonize::pythonize(py, &body).map_err(|e| {
1348	                            anyhow::anyhow!("Failed to convert request body to Python: {}", e)
1349	                        })?;
1350	
1351	                        // Call Python async function to get a coroutine
1352	                        let coroutine = callback.call1(py, (py_body,)).map_err(|e| {
1353	                            anyhow::anyhow!("Failed to call Python callback: {}", e)
1354	                        })?;
1355	
1356	                        // Use the TaskLocals captured at registration time
1357	                        pyo3_async_runtimes::into_future_with_locals(
1358	                            &locals,
1359	                            coroutine.into_bound(py),
1360	                        )
1361	                        .map_err(|e| {
1362	                            anyhow::anyhow!("Failed to convert coroutine to future: {}", e)
1363	                        })
1364	                    })?;
1365	
1366	                    // Await the Python coroutine (GIL is released during await)
1367	                    let py_result = py_future
1368	                        .await
1369	                        .map_err(|e| anyhow::anyhow!("Python callback failed: {}", e))?;
1370	
1371	                    // Convert result back to serde_json::Value
1372	                    Python::with_gil(|py| {
1373	                        pythonize::depythonize::<serde_json::Value>(py_result.bind(py))
1374	                            .map_err(|e| anyhow::anyhow!("Failed to serialize response: {}", e))
1375	                    })
1376	                })
1377	            });
1378	
1379	        self.inner
1380	            .engine_routes()
1381	            .register(&route_name, rust_callback);
1382	        tracing::debug!("Registered engine route: /engine/{}", route_name);
1383	        Ok(())
1384	    }
