1972	async fn process_stream(
1973	    stream: EngineStream<RsAnnotated<rmpv::Value>>,
1974	    tx: tokio::sync::mpsc::Sender<RsAnnotated<PyObject>>,
1975	) {
1976	    let mut stream = stream;
1977	    while let Some(response) = stream.next().await {
1978	        // Convert the response to a PyObject using Python's GIL
1979	        let annotated: RsAnnotated<rmpv::Value> = response;
1980	        let annotated: RsAnnotated<PyObject> = annotated.map_data(|data| {
1981	            Python::with_gil(|py| match pythonize::pythonize(py, &data) {
1982	                Ok(pyobj) => Ok(pyobj.into()),
1983	                Err(e) => Err(e.to_string()),
1984	            })
1985	        });
1986	
1987	        let is_error = annotated.is_error();
1988	
1989	        // Send the PyObject through the channel or log an error
1990	        if let Err(e) = tx.send(annotated).await {
1991	            tracing::error!("Failed to send response: {:?}", e);
1992	            break;
1993	        }
1994	
1995	        if is_error {
1996	            break;
1997	        }
1998	    }
1999	}
