83	{
84	    let stream = tokio::task::spawn_blocking(move || {
85	        Python::with_gil(|py| {
86	            let python_input = to_python_input(py)?;
87	
88	            // The closure returns the FULL kwarg list rather than just the
89	            // context, so a caller needing several keyword arguments builds
90	            // them all under one GIL acquisition. The push-egress path relies
91	            // on this to pass `context` and `response_sender` together.
92	            let gen_result = match to_python_kwargs {
93	                Some(to_python_kwargs) => {
94	                    let kwargs = to_python_kwargs(py)?;
95	                    let kwarg = PyDict::new(py);
96	                    for (name, value) in kwargs {
97	                        kwarg.set_item(name, value)?;
98	                    }
99	                    generator.call(py, (python_input,), Some(&kwarg))
100	                }
101	                // Legacy: no keyword arguments at all.
102	                None => generator.call1(py, (python_input,)),
103	            }?;
104	
105	            let locals = TaskLocals::new(event_loop.bind(py).clone());
106	            demand_driven_python_stream(locals, gen_result.into_bound(py))
107	        })
108	    })
109	    .await
110	    .map_err(|e| anyhow::anyhow!("failed to offload python call to blocking task: {e}"))??;
111	
112	    Ok(stream)
113	}
114	
115	fn demand_driven_python_stream(
116	    locals: TaskLocals,
117	    generator: Bound<'_, PyAny>,
118	) -> PyResult<PyItemStream> {
119	    let anext = generator.getattr("__anext__")?.unbind();
120	    let stream = futures::stream::unfold((anext, locals), |(anext, locals)| async move {
121	        let next = Python::with_gil(|py| {
122	            pyo3_async_runtimes::into_future_with_locals(&locals, anext.bind(py).call0()?)
123	        });
124	        let item = match next {
125	            Ok(next) => next.await,
126	            Err(error) => Err(error),
127	        };
128	        if item.as_ref().is_err_and(|error| {
129	            Python::with_gil(|py| {
130	                error.is_instance_of::<pyo3::exceptions::PyStopAsyncIteration>(py)
131	            })
132	        }) {
133	            None
134	        } else {
135	            Some((item, (anext, locals)))
136	        }
137	    });
138	    Ok(Box::pin(stream))
139	}
