291	async fn generate_python_stream<Req, Resp, ToPythonInput, ForwardResponses>(
292	    engine: &PythonServerStreamingEngine,
293	    request: SingleIn<Req>,
294	    to_python_input: ToPythonInput,
295	    forward_responses: ForwardResponses,
296	) -> Result<ManyOut<Resp>, Error>
297	where
298	    Req: Data,
299	    Resp: Data,
300	    ToPythonInput: FnOnce(Python, Req) -> PyResult<Py<PyAny>> + Send + 'static,
301	    ForwardResponses:
302	        FnOnce(PyItemStream, Arc<dyn AsyncEngineContext>, String) -> DataStream<Resp> + Send,
303	{
304	    let (request, context) = request.transfer(());
305	    let ctx = context.context();
306	    let id = context.id().to_string();
307	    tracing::trace!("processing request: {}", id);
308	
309	    let current_trace_context = get_distributed_tracing_context();
310	    let metadata = context.metadata().clone();
311	    let stream = invoke_generator(
312	        engine.generator.clone(),
313	        engine.event_loop.clone(),
314	        move |py| to_python_input(py, request),
315	        engine.has_context.then_some({
316	            let ctx = ctx.clone();
317	            move |py: Python<'_>| {
318	                Py::new(py, Context::new(ctx, current_trace_context, None, metadata))
319	                    .map(|context| vec![("context", context.into_any())])
320	            }
321	        }),
322	    )
323	    .await?;
324	
325	    let response_stream = forward_responses(stream, ctx, id);
326	    Ok(ResponseStream::new(response_stream, context.context()))
327	}
