329	/// Convert one Python response object into the wire value.
330	///
331	/// Yields tagged with `_dynamo_annotated: True` are wire `Annotated<R>`
332	/// envelopes; everything else is plain data.
333	///
334	/// Used by the typed pull path via [`process_item`]. The direct request-plane
335	/// paths — pull and push alike — instead go through
336	/// `python_payload::parse_python_response`, which keeps the payload a
337	/// `PythonPayload` so it transcodes straight into the wire codec.
338	///
339	/// The caller owns the error mapping; the GIL is already held.
340	fn depythonize_annotated<Resp>(
341	    bound: &Bound<'_, PyAny>,
342	) -> Result<Annotated<Resp>, pythonize::PythonizeError>
343	where
344	    Resp: for<'de> Deserialize<'de>,
345	{
346	    let is_envelope = bound
347	        .downcast::<PyDict>()
348	        .ok()
349	        .and_then(|d| {
350	            d.get_item(pyo3::intern!(bound.py(), "_dynamo_annotated"))
351	                .ok()
352	                .flatten()
353	        })
354	        .and_then(|v| v.is_truthy().ok())
355	        .unwrap_or(false);
356	
357	    if is_envelope {
358	        depythonize::<Annotated<Resp>>(bound)
359	    } else {
360	        depythonize::<Resp>(bound).map(Annotated::from_data)
361	    }
362	}
363	
364	async fn process_item<Resp>(
365	    item: Result<Py<PyAny>, PyErr>,
366	) -> Result<Annotated<Resp>, ResponseProcessingError>
367	where
368	    Resp: Data + for<'de> Deserialize<'de>,
369	{
370	    let item = item.map_err(|e| ResponseProcessingError::Dynamo(map_python_exception(e)))?;
371	    let response = tokio::task::spawn_blocking(move || {
372	        Python::with_gil(|py| depythonize_annotated::<Resp>(&item.into_bound(py)))
373	    })
374	    .await
375	    .map_err(|e| ResponseProcessingError::Offload(e.to_string()))?
376	    .map_err(|e| ResponseProcessingError::Deserialize(e.to_string()))?;
377	
378	    Ok(response)
379	}
