381	pub(crate) fn map_python_exception(error: PyErr) -> DynamoError {
382	    Python::with_gil(|py| {
383	        error.display(py);
384	
385	        if let Some((backend_err, message)) = py_exception_to_backend_error(py, &error) {
386	            return DynamoError::builder()
387	                .error_type(ErrorType::Backend(backend_err))
388	                .message(message)
389	                .build();
390	        }
391	
392	        if let Some((code, message)) = extract_http_like_error(py, &error) {
393	            let backend_err = if (400..500).contains(&code) {
394	                BackendError::InvalidArgument
395	            } else {
396	                BackendError::Unknown
397	            };
398	            let json_msg = serde_json::json!({
399	                "message": message,
400	                "code": code,
401	            })
402	            .to_string();
403	            return DynamoError::builder()
404	                .error_type(ErrorType::Backend(backend_err))
405	                .message(json_msg)
406	                .build();
407	        }
408	
409	        if error.is_instance_of::<pyo3::exceptions::PyGeneratorExit>(py) {
410	            return DynamoError::builder()
411	                .error_type(ErrorType::Backend(BackendError::EngineShutdown))
412	                .message("engine shutting down")
413	                .build();
414	        }
415	
416	        let backend_err = if error.is_instance_of::<pyo3::exceptions::PyValueError>(py)
417	            || error.is_instance_of::<pyo3::exceptions::PyTypeError>(py)
418	        {
419	            BackendError::InvalidArgument
420	        } else if error.is_instance_of::<pyo3::exceptions::PyTimeoutError>(py) {
421	            BackendError::ConnectionTimeout
422	        } else if error.is_instance_of::<pyo3::exceptions::PyConnectionRefusedError>(py) {
423	            BackendError::CannotConnect
424	        } else if error.is_instance_of::<pyo3::exceptions::PyConnectionResetError>(py)
425	            || error.is_instance_of::<pyo3::exceptions::PyBrokenPipeError>(py)
426	            || error.is_instance_of::<pyo3::exceptions::PyConnectionError>(py)
427	        {
428	            BackendError::Disconnected
429	        } else if error.is_instance_of::<pyo3::exceptions::asyncio::CancelledError>(py) {
430	            BackendError::Cancelled
431	        } else {
432	            BackendError::Unknown
433	        };
434	
435	        DynamoError::builder()
436	            .error_type(ErrorType::Backend(backend_err))
437	            .message(error.to_string())
438	            .build()
439	    })
440	}
