442	/// Channel depth between the response-forwarding task and the consumer of
443	/// the engine's output stream.
444	pub(crate) const RESPONSE_CHANNEL_DEPTH: usize = 128;
445	
446	/// Drain the Python response stream on a spawned task, deserialize each item
447	/// into `Resp` via [`process_item`], and forward it as an [`Annotated`] frame
448	/// over an mpsc channel. Returns the receiver, to be wrapped in a
449	/// [`ResponseStream`].
450	///
451	/// Errors raised by the Python generator are mapped to typed backend errors
452	/// and emitted as annotated error frames, so a failing generator returns as
453	/// an error to the client rather than a silently truncated stream.
454	/// On a deserialize mismatch the request context is told to stop generating.
455	/// The generator is not polled again until [`process_item`] has converted the
456	/// current `PyObject` into an owned Rust value, so this channel never buffers
457	/// mutable Python objects that a generator could reuse for a later yield.
458	fn spawn_response_forwarder<Resp>(
459	    stream: PyItemStream,
460	    ctx: Arc<dyn AsyncEngineContext>,
461	    request_id: String,
462	) -> mpsc::Receiver<Annotated<Resp>>
463	where
464	    Resp: Data + for<'de> Deserialize<'de>,
465	{
466	    let (tx, rx) = mpsc::channel::<Annotated<Resp>>(RESPONSE_CHANNEL_DEPTH);
467	
468	    // any error thrown in the stream will be caught and complete the
469	    // processing task; the error is emitted as an annotated error frame
470	    tokio::spawn(async move {
471	        tracing::debug!(
472	            request_id,
473	            "starting task to process python async generator stream"
474	        );
475	
476	        let mut stream = stream;
477	        let mut count = 0;
478	
479	        while let Some(item) = stream.next().await {
480	            count += 1;
481	            tracing::trace!(
482	                request_id,
483	                "processing the {}th item from python async generator",
484	                count
485	            );
486	
487	            let mut done = false;
488	
489	            let response = match process_item::<Resp>(item).await {
490	                Ok(response) => response,
491	                Err(e) => {
492	                    done = true;
493	
494	                    match e {
495	                        ResponseProcessingError::Deserialize(e) => {
496	                            // tell the python async generator to stop generating
497	                            ctx.stop_generating();
498	                            Annotated::from_error(format!(
499	                                "critical error: invalid response object from python async generator; application-logic-mismatch: {}",
500	                                e
501	                            ))
502	                        }
503	                        ResponseProcessingError::Dynamo(dynamo_err) => {
504	                            Annotated::from_err(dynamo_err)
505	                        }
506	                        ResponseProcessingError::Offload(e) => Annotated::from_error(format!(
507	                            "critical error: failed to offload the python async generator to a new thread: {}",
508	                            e
509	                        )),
510	                    }
511	                }
512	            };
513	
514	            if tx.send(response).await.is_err() {
515	                // Consumer dropped the response stream — tell the generator to
516	                // stop rather than relying solely on upstream push_handler.
517	                ctx.stop_generating();
518	                tracing::trace!(
519	                    request_id,
520	                    "error forwarding annotated response to channel; channel is closed"
521	                );
522	                break;
523	            }
524	
525	            if done {
526	                tracing::debug!(
527	                    request_id,
528	                    "early termination of python async generator stream task"
529	                );
530	                break;
531	            }
532	        }
533	
534	        tracing::debug!(
535	            request_id,
536	            "finished processing python async generator stream"
537	        );
538	    });
539	
540	    rx
541	}
