543	fn buffered_typed_response_stream<Resp>(
544	    stream: PyItemStream,
545	    ctx: Arc<dyn AsyncEngineContext>,
546	    request_id: String,
547	) -> DataStream<Annotated<Resp>>
548	where
549	    Resp: Data + for<'de> Deserialize<'de>,
