556	fn unbuffered_python_response_stream(
557	    stream: PyItemStream,
558	    ctx: Arc<dyn AsyncEngineContext>,
559	    request_id: String,
560	) -> DataStream<PythonResponseItem> {
561	    // Do not poll the generator again until ingress has encoded the current
562	    // Python object. A generator may reuse and mutate the same dict/list for
563	    // later yields; buffering raw PyObject handles would make earlier frames
564	    // observe those later mutations.
565	    Box::pin(DirectPythonResponseStream {
566	        stream: Some(stream),
567	        ctx,
