573	/// Demand-driven network response stream with cooperative Python cancellation.
574	///
575	/// Ingress stops the request context when the client response connection
576	/// closes, then drops this stream. Give the Python generator one final poll so
577	/// it can observe `context.is_stopped()` and run its cancellation path. Normal
578	/// response delivery remains unbuffered: the next generator item is not polled
579	/// until ingress has encoded the current one.
580	struct DirectPythonResponseStream {
581	    stream: Option<PyItemStream>,
582	    ctx: Arc<dyn AsyncEngineContext>,
583	    request_id: String,
584	    exhausted: bool,
585	}
586	
587	impl Stream for DirectPythonResponseStream {
588	    type Item = PythonResponseItem;
589	
590	    fn poll_next(mut self: Pin<&mut Self>, cx: &mut TaskContext<'_>) -> Poll<Option<Self::Item>> {
591	        let poll = self
592	            .stream
593	            .as_mut()
594	            .expect("direct Python response stream missing before exhaustion")
595	            .as_mut()
596	            .poll_next(cx);
597	        match poll {
598	            Poll::Ready(Some(item)) => {
599	                if item.is_err() {
600	                    self.exhausted = true;
601	                    self.stream.take();
602	                }
603	                Poll::Ready(Some(PythonResponseItem::new(item)))
604	            }
605	            Poll::Ready(None) => {
606	                self.exhausted = true;
607	                self.stream.take();
608	                Poll::Ready(None)
609	            }
610	            Poll::Pending => Poll::Pending,
611	        }
612	    }
613	}
614	
615	impl Drop for DirectPythonResponseStream {
616	    fn drop(&mut self) {
617	        if self.exhausted || !self.ctx.is_stopped() {
618	            return;
619	        }
620	
621	        let Some(mut stream) = self.stream.take() else {
622	            return;
623	        };
624	        let request_id = self.request_id.clone();
625	        let Ok(runtime) = tokio::runtime::Handle::try_current() else {
626	            return;
627	        };
628	        runtime.spawn(async move {
629	            // Cooperative Python generators inspect their Context when polled.
630	            // Discard the result: the client has already dropped its stream.
631	            let _ = stream.next().await;
632	            tracing::trace!(
633	                request_id,
634	                "polled direct Python response generator after cancellation"
635	            );
636	        });
637	    }
638	}
