640	/// Channel depth between the inbound forwarder and the Python iterator.
641	/// Mirrors the depth used by the wire-side bidirectional ingress forwarder
642	/// in `lib/runtime/src/pipeline/network/ingress/push_handler.rs`.
643	const BIDIRECTIONAL_INPUT_CHANNEL_DEPTH: usize = 8;
644	
645	/// Rust-side adapter that bridges a Python `async def generate(request_stream, context)`
646	/// callable into an [`AsyncEngine`] of the ManyIn / ManyOut
647	/// shape (`PythonPayload` request frames and raw Python response items).
648	///
649	/// The adapter:
650	///
651	/// 1. Transforms the inbound `RequestStream<PythonPayload>` into a
652	///    `PyAsyncRequestStream` and `context`. Similar to unary engine,
653	///    cancellation observation is the Python engine's responsibility via the
654	///    `context` argument. Input stream can end early if no more inputs are expected.
655	/// 2. Invokes the Python generator with `(request_stream, context)`, then
656	///    wraps the returned async generator into a Rust `Stream<Item = PyResult<PyObject>>`.
657	/// 3. Forwards each raw Python response to the ingress payload adapter, which
658	///    performs annotation handling and wire serialization in one blocking step.
659	pub struct PythonBidirectionalEngine {
660	    generator: Arc<PyObject>,
661	    event_loop: Arc<PyObject>,
662	    has_context: bool,
663	}
664	
665	impl PythonBidirectionalEngine {
666	    /// Build the adapter from a Python callable and an event loop. The
667	    /// callable should be an `async def generate(request_stream)` or
668	    /// `async def generate(request_stream, context)` returning an async
669	    /// generator of JSON-shaped response frames.
670	    pub fn new(generator: PyObject, event_loop: PyObject) -> PyResult<Self> {
671	        let has_context = detect_has_context(&generator);
672	        Ok(Self {
673	            generator: Arc::new(generator),
674	            event_loop: Arc::new(event_loop),
675	            has_context,
676	        })
677	    }
678	}
679	
680	#[async_trait::async_trait]
681	impl AsyncEngine<ManyIn<PythonPayload>, ManyOut<PythonResponseItem>, Error>
682	    for PythonBidirectionalEngine
683	{
684	    async fn generate(
685	        &self,
686	        input: ManyIn<PythonPayload>,
687	    ) -> Result<ManyOut<PythonResponseItem>, Error> {
688	        let (request_stream, ctx_unit) = input.into_parts();
689	        let ctx = ctx_unit.context();
690	        let request_id = ctx_unit.id().to_string();
691	        let metadata = ctx_unit.metadata().clone();
692	        let mut inbound = request_stream
693	            .take()
694	            .ok_or_else(|| anyhow::anyhow!("RequestStream::take returned None"))?;
695	
696	        // Capture trace context once, while we still hold the
697	        // dispatching task; needed when constructing the Python `Context`.
698	        let current_trace_context = get_distributed_tracing_context();
699	
700	        // Forwarder: move Python-owned frames directly into the Python
701	        // iterator. The `frame_tx.closed()` arm cancels the forwarder as soon
702	        // as the Python iterator drops the receiver, so it shuts down promptly
703	        // instead of blocking on the next inbound frame.
704	        let (frame_tx, frame_rx) = mpsc::channel::<PyObject>(BIDIRECTIONAL_INPUT_CHANNEL_DEPTH);
705	        let forwarder_request_id = request_id.clone();
706	        tokio::spawn(async move {
707	            loop {
708	                let value = tokio::select! {
709	                    _ = frame_tx.closed() => break,
710	                    value = inbound.next() => value,
711	                };
712	                let Some(value) = value else {
713	                    break;
714	                };
715	                if frame_tx.send(value.into_inner()).await.is_err() {
716	                    tracing::debug!(
717	                        request_id = %forwarder_request_id,
718	                        "python engine dropped request stream; input forwarder exiting"
719	                    );
720	                    break;
721	                }
722	            }
723	        });
724	
725	        let py_request_stream = PyAsyncRequestStream::new(frame_rx);
726	
727	        // The positional argument is the `PyAsyncRequestStream` handle, wrapped
728	        // inside the GIL.
729	        let stream = invoke_generator(
730	            self.generator.clone(),
731	            self.event_loop.clone(),
732	            move |py| Ok(Py::new(py, py_request_stream)?.into_any()),
733	            self.has_context.then_some({
734	                let ctx = ctx.clone();
735	                move |py: Python<'_>| {
736	                    Py::new(py, Context::new(ctx, current_trace_context, None, metadata))
737	                        .map(|c| vec![("context", c.into_any())])
738	                }
739	            }),
740	        )
741	        .await?;
742	
743	        let response_stream = unbuffered_python_response_stream(stream, ctx.clone(), request_id);
744	        Ok(ResponseStream::new(response_stream, ctx))
745	    }
746	}
